model Task {
  id: ID
  title: String
  completed: Bool = false
}

component TaskItem(task: Task, onDelete: Fn, onToggle: Fn) {
  row align=center gap=3 {
    checkbox task.completed -> onToggle(task.id)
    text task.title muted=task.completed
    button "×" small -> onDelete(task.id)
  }
}

page Home "/" {
  state input = ""
  state tasks: Task[] = []

  fn addTask() {
    if input.trim() == "" { return }
    tasks.push({ id: crypto.randomUUID(), title: input.trim(), completed: false })
    input = ""
  }

  fn toggleTask(id) {
    let task = tasks.find(t => t.id == id)
    if task { task.completed = !task.completed }
  }

  fn deleteTask(id) {
    tasks = tasks.filter(t => t.id != id)
  }

  computed pending = tasks.filter(t => !t.completed).length

  column gap=4 pad=4 {
    title "Mis Tareas"
    row gap=2 {
      input input placeholder="¿Qué hay que hacer?" -> addTask()
      button "Agregar" primary -> addTask()
    }
    column gap=2 {
      if tasks.length == 0 {
        text "No hay tareas" muted
      } else {
        for t in tasks key t.id {
          TaskItem task=t onDelete=deleteTask onToggle=toggleTask
        }
        text `${pending} pendientes` muted small
      }
    }
  }
}

