model Product {
  id: ID
  name: String
  price: Number
}

model CartItem {
  id: ID
  productId: ID
  name: String
  price: Number
  quantity: Number
}

component ShoppingCart() {
  state products: Product[] = [
    { id: "1", name: "Laptop", price: 999.99 }
    { id: "2", name: "Mouse", price: 29.99 }
    { id: "3", name: "Keyboard", price: 79.99 }
  ]

  state cart: CartItem[] = []

  fn addToCart(product: Product) {
    let item = cart.find(x => x.productId == product.id)
    if item {
      item.quantity++
    } else {
      cart.push({
        id: crypto.randomUUID()
        productId: product.id
        name: product.name
        price: product.price
        quantity: 1
      })
    }
  }

  fn increaseQuantity(itemId: ID) {
    let item = cart.find(x => x.id == itemId)
    if item {
      item.quantity++
    }
  }

  fn decreaseQuantity(itemId: ID) {
    let item = cart.find(x => x.id == itemId)
    if item {
      item.quantity--
      if item.quantity <= 0 {
        cart = cart.filter(x => x.id != itemId)
      }
    }
  }

  computed total = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0)

  column gap=6 pad=4 {
    title "Shopping Cart"

    row gap=6 {
      column gap=4 {
        title "Products" small
        for p in products {
          card gap=2 {
            text p.name bold
            text `$${p.price.toFixed(2)}` muted
            button "Add to Cart" primary -> addToCart(p)
          }
        }
      }

      column gap=4 {
        title "Cart" small
        if cart.length == 0 {
          text "Your cart is empty" muted
        } else {
          for item in cart {
            card gap=2 {
              row gap=2 justify=between {
                column {
                  text item.name bold
                  text `$${item.price.toFixed(2)}` muted
                }
                row gap=2 align=center {
                  button "-" -> decreaseQuantity(item.id)
                  text (item.quantity) bold
                  button "+" -> increaseQuantity(item.id)
                }
              }
            }
          }
          divider
          row gap=2 justify=between {
            title "Total:" small
            title `$${total.toFixed(2)}` small
          }
        }
      }
    }
  }
}

page Home "/" {
  ShoppingCart
}

