model User {
  id: ID
  name: String min=1
  email: Email
}

api users: User

page Home "/" {
  state name = ""
  state email = ""
  state error = ""

  fn validateAndAdd() {
    error = ""
    if !email.includes("@") {
      error = "Email inválido"
      return
    }
    try {
      api.users.create({ name, email })
      name = ""
      email = ""
    } catch (e) {
      error = e.message
    }
  }

  data allUsers = api.users.list()

  fn deleteUser(id) {
    try {
      api.users.remove(id)
    } catch (e) {
      error = e.message
    }
  }

  column gap=4 pad=4 {
    title "Usuarios"

    card gap=3 pad=3 {
      input name placeholder="Nombre"
      input email placeholder="Email" type=email
      if error {
        text error danger
      }
      button "Agregar" primary -> validateAndAdd()
    }

    if allUsers.loading {
      text "Cargando..." muted
    } else if allUsers.length == 0 {
      text "Sin usuarios" muted
    } else {
      column gap=2 {
        for user in allUsers key user.id {
          card gap=2 pad=2 {
            row align=center justify=between {
              column gap=1 {
                text user.name bold
                text user.email small muted
              }
              button "Borrar" danger small -> deleteUser(user.id)
            }
          }
        }
      }
    }
  }
}

model Item {
  id: ID
  name: String min=1
  purchased: Bool = false
}

api items: Item

page Home "/" {
  state newItem = ""
  data items = api.items.list()

  fn addItem() {
    if newItem.trim() == "" { return }
    api.items.create({ name: newItem })
    newItem = ""
  }

  fn markPurchased(id) {
    api.items.update(id, { purchased: true })
  }

  fn deleteItem(id) {
    api.items.remove(id)
  }

  computed pending = items.filter(i => !i.purchased).length

  column gap=4 pad=4 align=center {
    title "Lista de Compras"

    text `${pending} por comprar` bold

    row gap=2 {
      input newItem placeholder="Producto"
      button "Agregar" primary -> addItem()
    }

    if items.loading {
      spinner
    } else if items.length == 0 {
      text "Sin ítems" muted
    } else {
      column gap=2 {
        for item in items key item.id {
          row gap=2 align=center {
            text `${item.purchased ? "✓ " : ""}${item.name}` muted=item.purchased
            button "Comprado" small -> markPurchased(item.id) disabled=item.purchased
            button "Borrar" small danger -> deleteItem(item.id)
          }
        }
      }
    }
  }
}

