page Home "/" {
  data authors = api.authors.list()
  data posts = api.posts.list({ include: ["post.author"] })

  state newAuthorName = ""
  state newPostTitle = ""
  state selectedAuthorId = ""

  fn createAuthor() {
    if newAuthorName == "" { return }
    try {
      api.authors.create({ name: newAuthorName })
      newAuthorName = ""
      authors.reload()
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  fn createPost() {
    if newPostTitle == "" || selectedAuthorId == "" { return }
    try {
      api.posts.create({ title: newPostTitle, author: selectedAuthorId })
      newPostTitle = ""
      selectedAuthorId = ""
      posts.reload()
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  fn deleteAuthor(id) {
    try {
      api.authors.remove(id)
      authors.reload()
      posts.reload()
    } catch (e) {
      notify("El autor tiene posts", "danger")
    }
  }

  column gap=6 pad=4 {
    title "Blog"

    card pad=4 {
      title "Crear Autor" small
      row gap=2 {
        input newAuthorName placeholder="Autor"
        button "Crear autor" primary -> createAuthor()
      }
    }

    card pad=4 {
      title "Publicar Post" small
      column gap=2 {
        input newPostTitle placeholder="Título"
        select selectedAuthorId options=authors.map(a => ({ value: a.id, label: a.name })) placeholder="Selecciona un autor"
        button "Publicar" primary -> createPost()
      }
    }

    card pad=4 {
      title "Autores" small
      if authors.length == 0 {
        text "No hay autores" muted
      } else {
        column gap=2 {
          for author in authors {
            row gap=2 align=center justify=between {
              text author.name
              button "Borrar" danger small -> deleteAuthor(author.id)
            }
          }
        }
      }
    }

    card pad=4 {
      title "Posts" small
      if posts.length == 0 {
        text "No hay posts" muted
      } else {
        column gap=3 {
          for post in posts {
            card pad=3 {
              title post.title small
              text `por ${post.author.name}` muted small
            }
          }
        }
      }
    }
  }
}

