page Items "/items" {
  state page = 1
  state itemsPerPage = 10

  computed totalItems = 23
  computed totalPages = Math.ceil(totalItems / itemsPerPage)
  computed startIndex = (page - 1) * itemsPerPage
  computed endIndex = Math.min(startIndex + itemsPerPage, totalItems)
  computed currentItems = Array.from({ length: endIndex - startIndex }, (_, i) => startIndex + i + 1)

  fn previousPage() {
    if page > 1 { page-- }
  }

  fn nextPage() {
    if page < totalPages { page++ }
  }

  column gap=4 pad=4 {
    title "Items"

    for itemNum in currentItems {
      text `Ítem ${itemNum}`
    }

    row gap=4 align=center {
      text `Página ${page} de ${totalPages}`
      button "Anterior" disabled=(page == 1) -> previousPage()
      button "Siguiente" disabled=(page == totalPages) -> nextPage()
    }
  }
}

