page App "/" {
  state time = 0
  state running = false
  state intervalId = null

  fn start() {
    if running { return }
    running = true
    intervalId = setInterval(() => {
      time++
    }, 100)
  }

  fn pause() {
    running = false
    if intervalId != null {
      clearInterval(intervalId)
      intervalId = null
    }
  }

  fn reset() {
    running = false
    if intervalId != null {
      clearInterval(intervalId)
      intervalId = null
    }
    time = 0
  }

  mount {
    cleanup {
      if intervalId != null {
        clearInterval(intervalId)
      }
    }
  }

  column gap=4 align=center pad=8 {
    title "Cronómetro"
    text `Tiempo: ${time}` large
    row gap=2 {
      button "Iniciar" primary -> start() disabled=running
      button "Pausar" -> pause() disabled=!running
      button "Reiniciar" danger -> reset()
    }
  }
}

