      row gap=2 align=center {
        text `${task.title}${task.done ? " (hecha)" : ""}`
        if !task.done {
          button "Hecha" small -> markDone()
          button "Renombrar" small -> startEdit()
        }
      }
    }
  }
}

page Tasks "/tasks" {
  state taskInput = ""
  state filter = "Todas"
  data allTasks = api.tasks.list()

  fn addTask() {
    if taskInput.trim() == "" { return }
    api.tasks.create({ title: taskInput, done: false })
    taskInput = ""
  }

  fn updateTask(id, changes) {
    api.tasks.update(id, changes)
  }

  computed filteredTasks = {
    if filter == "Pendientes" {
      return allTasks.filter(t => !t.done)
    } else if filter == "Hechas" {
      return allTasks.filter(t => t.done)
    }
    return allTasks
  }

  column gap=4 pad=4 align=center {
    title "Gestor de Tareas"

    row gap=2 {
      input taskInput placeholder="Tarea" -> { if event.key == "Enter" { addTask() } }
      button "Agregar" primary -> addTask()
    }

    select filter options=["Todas", "Pendientes", "Hechas"]

    if allTasks.loading {
      spinner
    } else if filteredTasks.length == 0 {
      text "No hay tareas" muted
    } else {
      column gap=2 {
        for t in filteredTasks {
          card {
            TaskItem task=t onUpdate=updateTask
          }
        }
      }
    }
  }
}

