model Vote {
  id: ID
  option: String
  createdAt: Date
}

page Home "/" {
  data votes = api.votes.list()

  fn getStats() {
    let total = votes.length
    if total == 0 {
      return { dogs: 0, cats: 0, dogsPercent: 0, catsPercent: 0 }
    }
    let dogs = votes.filter(v => v.option == "dogs").length
    let cats = votes.filter(v => v.option == "cats").length
    let dogsPercent = Math.round((dogs / total) * 100)
    let catsPercent = Math.round((cats / total) * 100)
    return { dogs, cats, dogsPercent, catsPercent }
  }

  fn vote(option) {
    try {
      await api.votes.create({ option })
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  fn reset() {
    try {
      let allVotes = await api.votes.list()
      for v in allVotes {
        await api.votes.remove(v.id)
      }
      await votes.reload()
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  let stats = getStats()

  column gap=4 align=center pad=6 {
    title "¿Perros o Gatos?"

    card pad=4 {
      column gap=4 {
        column gap=2 {
          text "Perros" bold
          text `${stats.dogsPercent}% (${stats.dogs} votos)` muted
        }
        button "Votar Perros" primary -> vote("dogs")
      }
    }

    card pad=4 {
      column gap=2 {
        text "Gatos" bold
        text `${stats.catsPercent}% (${stats.cats} votos)` muted
      }
      button "Votar Gatos" primary -> vote("cats")
    }

    divider

    button "Reiniciar" danger small -> reset()
  }
}

